CREATE TABLE public.safety_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),name text NOT NULL,items text[] NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.safety_templates TO authenticated; GRANT ALL ON public.safety_templates TO service_role; ALTER TABLE public.safety_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY safety_read ON public.safety_templates FOR SELECT TO authenticated USING(company_id=public.current_company_id()); CREATE POLICY safety_manage ON public.safety_templates FOR ALL TO authenticated USING(company_id=public.current_company_id() AND public.has_company_role('admin')) WITH CHECK(company_id=public.current_company_id() AND public.has_company_role('admin'));
CREATE TABLE public.fault_library(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),trade text NOT NULL DEFAULT '',fault text NOT NULL,remedy text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fault_library TO authenticated; GRANT ALL ON public.fault_library TO service_role; ALTER TABLE public.fault_library ENABLE ROW LEVEL SECURITY;
CREATE POLICY faults_read ON public.fault_library FOR SELECT TO authenticated USING(company_id=public.current_company_id()); CREATE POLICY faults_manage ON public.fault_library FOR ALL TO authenticated USING(company_id=public.current_company_id() AND public.has_company_role('admin')) WITH CHECK(company_id=public.current_company_id() AND public.has_company_role('admin'));
ALTER TABLE public.job_sheets ADD COLUMN checklist_snapshot text[] NOT NULL DEFAULT '{}',ADD COLUMN safety_snapshot text[] NOT NULL DEFAULT '{}';
CREATE FUNCTION public.capture_sheet_requirements() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.maintenance_agreements; items text[]; BEGIN
 IF TG_OP='INSERT' THEN SELECT coalesce(array_agg(item),'{}') INTO NEW.safety_snapshot FROM public.safety_templates t CROSS JOIN LATERAL unnest(t.items) item WHERE t.company_id=NEW.company_id AND t.enabled; END IF;
 IF TG_OP='UPDATE' THEN NEW.safety_snapshot=OLD.safety_snapshot; NEW.checklist_snapshot=OLD.checklist_snapshot; END IF;
 IF NEW.is_maintenance AND (TG_OP='INSERT' OR NOT OLD.is_maintenance OR (OLD.status<>'completed' AND (OLD.client_id IS DISTINCT FROM NEW.client_id OR OLD.site_id IS DISTINCT FROM NEW.site_id OR OLD.asset_type IS DISTINCT FROM NEW.asset_type))) THEN
 SELECT * INTO a FROM public.maintenance_agreements WHERE company_id=NEW.company_id AND client_id=NEW.client_id AND status='active' AND start_date<=current_date AND end_date>=current_date AND (site_id=NEW.site_id OR site_id IS NULL) ORDER BY site_id NULLS LAST,created_at DESC LIMIT 1;
 SELECT coalesce(array_agg(value),'{}') INTO items FROM jsonb_array_elements_text(coalesce(a.terms_snapshot->'checklist'->'items','[]')) value;
 IF cardinality(items)=0 THEN SELECT coalesce(array_agg(value),'{}') INTO items FROM public.checklist_templates t CROSS JOIN LATERAL jsonb_array_elements_text(t.items) value WHERE t.company_id=NEW.company_id AND t.id=(SELECT id FROM public.checklist_templates WHERE company_id=NEW.company_id AND equipment_category=CASE NEW.asset_type WHEN 'Lift' THEN 'Elevator' WHEN 'Escalator' THEN 'Escalator' ELSE coalesce(NEW.asset_type_other,'Custom') END ORDER BY created_at DESC LIMIT 1); END IF;
 NEW.checklist_snapshot=coalesce(items,'{}'); END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_sheet_requirements BEFORE INSERT OR UPDATE ON public.job_sheets FOR EACH ROW EXECUTE FUNCTION public.capture_sheet_requirements();
CREATE FUNCTION public.guard_sheet_requirements() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.status='completed' AND OLD.status<>'completed' THEN
 IF EXISTS(SELECT 1 FROM unnest(NEW.safety_snapshot) i WHERE coalesce(NEW.checklist_values->>('safety:'||i),'false')<>'true') THEN RAISE EXCEPTION 'Complete the safety assessment before signing'; END IF;
 IF NEW.is_maintenance AND EXISTS(SELECT 1 FROM unnest(NEW.checklist_snapshot) i WHERE coalesce(NEW.checklist_values->>i,'false')<>'true') THEN RAISE EXCEPTION 'Complete the assigned maintenance checklist before signing'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER z_guard_sheet_requirements BEFORE UPDATE ON public.job_sheets FOR EACH ROW EXECUTE FUNCTION public.guard_sheet_requirements();
CREATE TABLE public.client_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),sheet_id uuid NOT NULL REFERENCES public.job_sheets(id) ON DELETE RESTRICT,token_hash text NOT NULL UNIQUE,snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days',revoked_at timestamptz,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.client_reports TO authenticated; GRANT ALL ON public.client_reports TO service_role; ALTER TABLE public.client_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_manage ON public.client_reports FOR ALL TO authenticated USING(company_id=public.current_company_id() AND public.is_company_manager()) WITH CHECK(company_id=public.current_company_id() AND public.is_company_manager());
CREATE FUNCTION public.guard_client_report() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_OP='UPDATE' AND (NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.sheet_id IS DISTINCT FROM OLD.sheet_id OR NEW.token_hash IS DISTINCT FROM OLD.token_hash OR NEW.created_by IS DISTINCT FROM OLD.created_by) THEN RAISE EXCEPTION 'Reports are immutable; create a new link'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.job_sheets WHERE id=NEW.sheet_id AND company_id=NEW.company_id AND status='completed') THEN RAISE EXCEPTION 'Report requires a completed company sheet'; END IF; RETURN NEW; END $$;
CREATE TRIGGER client_report_guard BEFORE INSERT OR UPDATE ON public.client_reports FOR EACH ROW EXECUTE FUNCTION public.guard_client_report();
CREATE FUNCTION public.read_client_report(_hash text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT snapshot FROM public.client_reports WHERE token_hash=_hash AND revoked_at IS NULL AND expires_at>now() $$;
REVOKE ALL ON FUNCTION public.read_client_report(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.read_client_report(text) TO anon,authenticated;
CREATE FUNCTION public.guard_module_write_additional() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.company_module_access(CASE WHEN TG_OP='DELETE' THEN OLD.company_id ELSE NEW.company_id END,TG_ARGV[0]) THEN RAISE EXCEPTION 'This module is read-only for your company'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER commercial_guard BEFORE INSERT OR UPDATE OR DELETE ON public.safety_templates FOR EACH ROW EXECUTE FUNCTION public.guard_module_write_additional('safety'); CREATE TRIGGER commercial_guard BEFORE INSERT OR UPDATE OR DELETE ON public.fault_library FOR EACH ROW EXECUTE FUNCTION public.guard_module_write_additional('safety');